import subprocess, sys, difflib
from collections import defaultdict

upstream = sys.argv[1]

def git(*args, check=True):
    p = subprocess.run(["git"] + list(args), capture_output=True)
    if check and p.returncode != 0:
        sys.stderr.write(p.stderr.decode())
        sys.exit(p.returncode)
    return p

def show(rev_path):
    p = git("show", rev_path, check=False)
    if p.returncode != 0:
        return None
    return p.stdout

base = git("merge-base", "HEAD", "MERGE_HEAD").stdout.decode().strip()

def changed(rev):
    out = git("diff", "--name-only", "-z", base, rev).stdout
    return [x.decode() for x in out.split(b'\0') if x]

common = set(changed("HEAD")) & set(changed("MERGE_HEAD"))

for path in common:
    upstream_content = show(upstream + ":" + path)
    if upstream_content is None:
        git("rm", "-f", "--", path)
        continue

    base_content = show(base + ":" + path) or b""
    local_content = show("HEAD:" + path) or b""

    base_lines = base_content.splitlines(keepends=True)
    local_lines = local_content.splitlines(keepends=True)
    upstream_lines = upstream_content.splitlines(keepends=True)

    sm = difflib.SequenceMatcher(None, base_lines, local_lines, autojunk=False)
    insertions = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'insert':
            insertions.append((i1 - 1, local_lines[j1:j2]))

    sm2 = difflib.SequenceMatcher(None, base_lines, upstream_lines, autojunk=False)
    base_to_up = dict()
    for tag, i1, i2, j1, j2 in sm2.get_opcodes():
        if tag == 'equal':
            for k in range(i2 - i1):
                base_to_up[i1 + k] = j1 + k

    def target(anchor):
        if anchor < 0:
            return 0
        if anchor in base_to_up:
            return base_to_up[anchor] + 1
        prev = anchor - 1
        while prev >= 0 and prev not in base_to_up:
            prev -= 1
        if prev >= 0:
            return base_to_up[prev] + 1
        nxt = anchor + 1
        while nxt < len(base_lines) and nxt not in base_to_up:
            nxt += 1
        if nxt < len(base_lines):
            return base_to_up[nxt]
        return len(upstream_lines)

    ins_by = defaultdict(list)
    for anchor, added in insertions:
        ins_by[target(anchor)].extend(added)

    result = []
    for i in range(len(upstream_lines) + 1):
        if i in ins_by:
            result.extend(ins_by[i])
        if i < len(upstream_lines):
            result.append(upstream_lines[i])

    with open(path, 'wb') as f:
        f.write(b''.join(result))
    git("add", "--", path)

unmerged_out = git("diff", "--name-only", "--diff-filter=U", "-z").stdout
for path in [x.decode() for x in unmerged_out.split(b'\0') if x]:
    upstream_content = show(upstream + ":" + path)
    if upstream_content is None:
        git("rm", "-f", "--", path)
    else:
        with open(path, 'wb') as f:
            f.write(upstream_content)
        git("add", "--", path)

